"""Conveyor V0.9 skill catalogue; rule revision supplied 2026-10-29."""
SKILLS = {}

def skill(key, name, group, deal, keep, text):
    SKILLS[key] = dict(id=key, name=name, group=group, deal=deal, keep=keep, text=text)

skill('balance', '转换', 0, 7, 7, '轮到你时，选几张手牌，点击“发动转换”：弃掉这些牌，再获得同样数量的牌。\n换完就结束这次行动，不再出牌，也不额外发牌。')
skill('anchor', '稳阵', 0, 8, 6, '急牌轮换时，你保留自己的手牌，不参与交换。\n急牌让你抓两张时只抓一张，禁手两回合时只禁一回合。禁手可以叠加。')
skill('leap', '跨级', 0, 10, 8, '你的 3 至 A 提高两级，小王按大王使用。2 和主牌不变。\n加点时不跳过主牌原来的位置，经过 A、2 后最高到主牌。例如主牌是 3 时，J 变 K，K 变 2，A 变主牌。手牌会同时显示原点数和实际点数。')
skill('stars', '守望', 0, 9, 6, '拿到自由牌权时，你可以调整牌堆顶部的顺序。展示张数等于所有未走完身份的普通手牌总张数，不含特殊区域。\n按想要的顺序依次点击所有展示牌，再确认；先点的牌放在最上面。牌堆不够时，有几张就排几张。')
skill('reflux', '回收', 0, 8, 7, '出牌后，你可以把刚出的任意几张牌放回牌堆底，也可以全不放。\n一次出四张或更多时，其他玩家各抓“出牌数减二”张。比如出四张，别人各抓两张。')
skill('clean', '净化', 0, 8, 4, '拿到 3、4、5、6 时，把它们弃掉并补牌，直到拿到能留下的牌。开局发牌也一样，在选牌期间也不会拿到这四张牌。\n如果其中有本局主牌，必须保留主牌，其余换掉。')
skill('money', '聚宝', 0, 9, 6, '每出一张牌获得一金钱，金钱进入展示区作为金钱标记。\n别人出牌后，你可以花四金钱买走其中一张，也可以放弃。买到的牌加入手牌；桌上仍显示对方原来的完整出牌，并播报你买了哪张。已被收走的牌不能买。')
skill('gift', '恩赐', 1, 7, 7, '轮到你时，选一张手牌送给另一名玩家，自己再抓两张。\n送完就结束这次行动，不再出牌，也不额外发牌。')
skill('stash', '藏拙', 1, 20, 12, '行动结束时，手牌少于五张就不用发牌。\n出牌后，你可以把剩下的任意几张手牌不公示地存入展示区，之后随时将展示区的牌取回。展示区不受急牌影响，但里面的牌仍要出完；只清空手牌不算走完。')
skill('scavenge', '顺手牵羊', 1, 8, 1, '可选择跳过出牌阶段，前两次轮到你时，必须跳过出牌阶段。跳过出牌阶段时，改为拿走另一名玩家最近一次出牌中的至少一张。一次可拿多张，但要来自同一个人。\n跳过出牌阶段不发结束牌。不可做第一个出牌者。')
skill('pressure', '施压', 1, 14, 12, '随时可以消耗一张实际点数为 2 的牌，指定另一名玩家抓四张。\n用完后你仍可以继续出牌。')
skill('suitmark', '烙印', 1, 9, 9, '用至少两种花色的牌管住别人，并拿到自由牌权后，给被管者一个花色印记，展示在展示区。如果出多张牌，由出牌者决定使用什么印记。\n对方攒到两个印记后，立即结算并清除：\n♠♠：抓两张。\n♥♥：弃掉两张最大的牌。\n♣♣：看两张，最多留一张。\n♦♦：无效果。\n♠♥：抓两张，再弃掉一张最大的牌。\n♠♣：抓一张，再看一张，自选是否留下。\n♥♣：弃掉一张最大的牌，再看一张，自选是否留下。\n♠♦：抓四张。\n♥♦：弃掉三张最大的牌。\n♣♦：看三张，最多留一张。\n没留下的牌进入弃牌堆。')
skill('double', '拆解', 1, 7, 5, '每次出牌，你可以把一张 K、A、2 或主牌当成两张 3、4、5 来用，但不能变成本局主牌。两张的点数和花色由你分别指定。\n选好原牌后点“拆解”，指定结果，再和其他牌一起出。每次只能拆解一张原牌；出牌数量按两张算，实际只消耗这一张。')
skill('seven', '重铸·七音', 2, 8, 8, '轮到你时，可以把 3、4、5、6 存成印记，最多七枚，作为七音印记记入展示区。\n攒满七枚后，点“使用重铸·七音”，指定七张牌的点数和花色，组成七连顺子出牌，随后消耗全部七音印记。存成印记的牌不再需要出完。')
skill('formless', '重铸·万化', 2, 8, 6, '你可以忽略花色来“回”，而且一轮内不限次数。牌型和张数仍须与对方相同。\n手牌少于三张时不能回。王、2 和主牌仍不能作为回牌或被回牌的主体。')
skill('blood', '重铸·嗜血', 2, 10, 5, '开局选牌弃掉的五张牌合计获得一枚嗜血印记，记在展示区。\n每出一次牌减一枚；未出牌时，每获得一张牌加一枚，最低为零。\n行动结束不进行通常发牌，而是弃牌或补牌，使普通手牌数等于嗜血印记数。这次补牌不增加嗜血印记；牌堆不足时只补现有的牌。')
skill('ascend', '重铸·至高强化', 2, 8, 8, '你的 3 至 A 初始提高一级，2、主牌和王不变。加点时不会跳过主牌原来的位置，最高到主牌，手牌会标出变化。\n轮到你时，可以弃掉印面为 2 的牌，作为一枚至高强化印记。每枚至高强化印记使你本局加点幅度再加一级，比如从加一变成加二。')
skill('extra', '重铸·丰收', 2, 6, 2, '普通行动结束发牌时，你可以选择抓一、二或三张。\n急牌和其他技能规定的抓牌数量不变。')
skill('redirect', '替身', 3, 6, 1, '普通行动结束发牌时，你可以让另一名玩家替你抓一张，自己不抓；也可以照常自己抓。')
skill('request', '窃取', 3, 9, 3, '普通行动结束时，你可以不从牌堆抓牌，改为向其他每个在场玩家各要两张，由对方选牌。\n不足两张就全部交出；有人因此出空普通手牌，就视为走完，未出展示区的牌进入弃牌堆。前两次行动的补牌限制仍适用。')
skill('gather', '取舍', 3, 12, 6, '你拿到的 2、主牌和大小王会被弃掉，再补其他牌，开局发牌也一样。急牌可以保留。\n普通行动结束发牌时，可以选择抓一至五张。')
skill('wild', '千变', 3, 10, 10, '你的所有 A 都能当赖子，也能按原本的 A 出。选中 A 后点“指定赖子”，逐张选择它代替的点数和花色，再出牌。\n不可替代王牌、急牌，普通替代要和其他牌一起出。回牌按指定后的花色判断，桌上会显示原牌和替代结果。')
skill('twins', '如影随形', 3, 14, 14, '你算作两个玩家。\n开局把手牌分成两组，每组均为七张。你控制两个身份，依次行动，用“手牌 A／B”切换。\n两个身份各自出牌、发牌、计算状态，也能分别被技能或急牌选中。任意一个身份走完，你就走完，另一个停止行动。界面仍是四个真人座位，你有两个出牌区；规则中按五个独立行动者计算，组队和升级按四名真人计算。')
skill('pursuit', '追猎', 3, 6, 3, '轮到你时，如果没有能管上的牌，就一直抓，抓到能管上为止，最多十张。抓满还管不上就不出。\n一旦手牌可以以任意方式管上，就不再有任意形式的抓牌，他人技能和急牌除外。\n停止抓牌时可选择不出。结束行动时不抓牌。')
skill('debt', '奉还', 3, 9, 6, '每管上别人一次，就给对方一枚奉还印记，记入展示区，可以累积。\n当你拿到自由牌权时，其他在场玩家各抓自己印记数那么多张牌，然后清除所有印记。')
skill('judgment', '投骰', 4, 12, 12, '轮到你且没有能管上的牌时，可以翻牌堆顶一张判定。翻到黑桃 2 至 9，就视为出了相同牌型、主体大一级的牌；花色和带牌与上一名玩家相同。\n此判定不可以用于“压”“死压”和“死点”。\n失败就抓五张并跳过出牌，再按行动结算结束发牌。')
skill('trade', '献祭', 4, 10, 2, '轮到你时，可以用一张王换五张牌、主牌换四张、2 换三张。换完还能继续出牌。\n普通结束发牌时，还可以翻一张判定牌：黑色允许额外抓一至十三张，其余花色没有额外效果。')
skill('bond', '灵魂绑定', 4, 9, 3, '开局选择另一名玩家的一手牌绑定，自己的回合可以更换目标；绑定持续到更换为止。双方能看到对方手牌和未公开的展示区。\n绑定期间，双方普通结束行动发牌可选一至两张。结束行动、技能或急牌使一方获得牌时，另一方也获得相同数量；不同步弃牌，也不会来回重复触发。')
skill('duel', '死斗', 4, 8, 6, '拿到自由牌权时，可以发起拼点。所有在场玩家各暗选一张牌，选齐后同时公开并弃掉，作为判定牌。\n除你之外，判定牌不大于你的玩家，还要弃掉最大的三张手牌；不足三张就保留最小的一张。按技能改变后的点数比较。')
skill('formation', '节流', 4, 9, 9, '出 4A4A4 牌型时，可省略一张 4 和一张 A，即 4A4 为基础 4A4A4，更大的为 444A，以此类推。\n出牌前手牌多于十二张时，三张同点就能当炸弹。剩十二张或更少时，恢复四张起炸。')

skill('redemption', '救赎之力', 5, 8, 6, '获得自由牌权时，清除所有玩家展示区内的牌和所有印记，清除的实体牌进入弃牌堆，视为已出。\n同一次清除中，每种印记只计一次；每清除一种，可以自选弃置一张手牌，也可以少弃或不弃。')
skill('chase_force', '追击之力', 5, 14, 14, '你的所有牌初始降低一级。\n将所有未走完身份的普通手牌相加，不计特殊区域。总张数每比参与玩家人数少一张，你的牌值增加两级；总张数多于参与玩家人数时，改为增加五级。\n所有牌都参与升降，按 3 至 A、2、主牌、小王、大王、急牌的顺序变化，最低为 3、最高为急牌；手牌显示原点数与当前点数。')
skill('equilibrium', '平衡之力', 5, 12, 12, '普通手牌比你多的玩家，一次最多获得一张牌，结束发牌、技能和急牌均受限制。\n普通手牌比你多九张及以上的玩家不能出炸弹；超过九张的部分，每多一张，所有牌值降低一级，最低为 3。数量变化后立即重新计算。')
skill('shadow', '阴影之力', 5, 8, 8, '获得自由牌权后，封禁下一位行动者和被你管住的玩家的技能，并使他们禁手一次。若两者为同一身份，只施加一次。\n技能封禁持续到该身份下一次行动结束；跳过出牌后仍按规则结算发牌。')
skill('imprison', '禁锢之力', 5, 8, 8, '除你之外，玩家在普通结束发牌以外获得牌时，每张获得一枚禁锢印记，公开展示。\n每次整批获牌后结算：达到两枚及以上就清除该玩家全部禁锢印记，并禁手“印记数减一”回合。例如一次获得四张，则禁手三回合。')
skill('encourage', '激励之力', 5, 12, 10, '从本次轮到你至下次轮到你之前，获得的第一张牌不加印记，此后每获得一张牌加一枚激励印记，公开展示。\n获得自由牌权时，可消耗任意枚激励印记，每枚自选弃置一张手牌，也可不使用。未用的印记保留。')

GROUPS = {0: '标准', 1: '突破', 2: '重生', 3: '多多益善', 4: '智谋', 5: '终极力量'}

def available(options):
    groups = {0} | set(options.get('skillDlc', []))
    disabled = set(options.get('disabledSkills', []))
    return [s for s in SKILLS.values() if s['group'] in groups and s['id'] not in disabled]
